// src/api/client.js
import { API_URL } from "./config";

export async function apiFetch(path, options = {}) {
  const token = localStorage.getItem("access");

  return fetch(`${API_URL}${path}`, {
    ...options,
    headers: {
      ...(options.headers || {}),
      ...(token && { Authorization: `Bearer ${token}` }),
    },
  }).then(res => res.json());
}
